INSERT INTO tb_lojas (id, nome, descricao, categoria, imagem_url, is_aberto, taxa_entrega_base, tempo_entrega_min, tempo_entrega_max, avaliacao_media, total_avaliacoes, end_rua, end_numero, end_cidade, end_estado, end_cep, geo_lat, geo_lng, geo_geohash, horario_domingo, horario_segunda, horario_terca, horario_quarta, horario_quinta, horario_sexta, horario_sabado) VALUES 
('loja_0001', 'Sweet King', 'Yoshinoya is in business to create the structure and systems needed to allow our customers access to the majority of their away-from-home daily meal requirements on a one-stop-shop basis. All our products shall be of the highest quality and value, be healthy, nutritious and provided with outstanding personal services at the lowest possible prices consistent with a fair return on investment for our shareholders, job enhancementsecurity for our employees and a level of community involvement by everyone connected with our business. All of our products and services shall be delivered consistently and measured one satisfied customer at a time, whether by company-owned or franchised operations, in superior, clean, convenient, fun and friendly neighborhood environments. We pledge to make Yoshinoya the best place to eat and the best place to work.', 'Brasileira', 'https://picsum.photos/seed/loja_0001/400', false, 8.47, 29, 42, 3.6, 419, 'Travessa Ricardo Passarinho', '6815', 'Abrantes', 'SP', '75886498', -22.30860027, 105.20128889, NULL, '11:00 - 23:00', 'Fechado', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00'),
('loja_0002', 'Blue Curry', 'To achieve and maintain such distinction in food and wine, service, atmosphere and setting that the restaurant gains a first class reputation for gastronomy, gracious and informed hospitality, comfort and beauty which draws new and repeat customers year after year. To achieve the above whilst upholding staff policies and practices which promote a fair and positive working environment. To be aware of and act on our responsibilities as a good corporate citizen to  provide a safe, clean and attractive place for guests to enjoy and for employees to work in - ensure ecologically sound management practices at the restaurant and in our surrounding gardens and woods - undertake meaningful involvement of Restaurant Les Fougères in selected charitable activities in our community and region.', 'Lanches', 'https://picsum.photos/seed/loja_0002/400', true, 5.95, 24, 48, 4.2, 1530, 'Rodovia Davi Lucca Barros', '083', 'Vila do Conde', 'BA', '16105021', 67.32588421, -171.99428359, NULL, '11:00 - 23:00', 'Fechado', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00'),
('loja_0003', 'Spice Bakery', 'To ensure that each guest receives prompt, professional, friendly and courteous service. To maintain a clean, comfortable and well maintained premises for our guests and staff. To provide at a fair price – nutritional, well-prepared meals – using only quality ingredients. To ensure that all guests and staff are treated with the respect and dignity they deserve. To thank each guest for the opportunity to serve them. By maintaining these objectives we shall be assured of a fair profit that will allow us to contribute to the community we serve.', 'Japonesa', 'https://picsum.photos/seed/loja_0003/400', true, 10.82, 28, 40, 3.3, 218, 'Rodovia Arthur Miguel', '669', 'Beja', 'GO', '93953664', 72.65877775, -73.83361864, NULL, '11:00 - 23:00', 'Fechado', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00', '11:00 - 23:00'),
